def latest(a):
    n,num,k=a
    try:
        r=urllib.request.Request("https://obscurify.ai/transactions",headers={"Authorization":f"Bearer {k}"})
        with urllib.request.urlopen(r,timeout=30) as x: items=json.load(x).get("transactions",[])
        use=[t for t in items if t.get("label")=="Usage"]
        if not use: return (n,num,"-",0,0.0)
        last=max(t["created_at"] for t in use)
        return (n,num,last,len(use),sum(abs(float(t["amount"])) for t in use))
    except Exception: return (n,num,"ERR",0,0.0)
res=[]
with concurrent.futures.ThreadPoolExecutor(max_workers=10) as ex:
    for r in ex.map(latest,acc): res.append(r)
ok=[r for r in res if r[2] not in ("-","ERR")]
ok.sort(key=lambda r:r[2],reverse=True)
print("=== 10 akun dengan transaksi PALING BARU ===")
print(f"{'waktu terakhir':26} {'req':>4} {'spent':>9}  akun")
for n,num,last,cnt,sp in ok[:10]:
    print(f"{last[:19]:26} {cnt:4} {sp:9.4f}  {num} (baris {n})")
print(f"\ntotal akun punya riwayat: {len(ok)} dari {len(acc)}")
